<script setup>
import {ref,watch} from 'vue';import {api} from './api';import MathText from './MathText.vue';
const props=defineProps({paperIds:{type:Array,default:()=>[]}});const emit=defineEmits(['saved']);
const text=ref(''),replace=ref(false),busy=ref(false),error=ref(''),notice=ref(''),rows=ref([]),validated=ref('');
watch([text,replace],()=>{rows.value=[];validated.value=''});
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function exportBundle(){window.location.href='/api/admin/ai-solutions/bundle/export?ids='+props.paperIds.join(',')}
async function readFile(event){await run(async()=>{const f=event.target.files?.[0];if(!f)return;if(f.size>8000000)throw Error('Use a JSON file below 8 MB.');text.value=await f.text()})}
async function preview(){await run(async()=>{const d=await api('/admin/ai-solutions/bundle/import',{method:'POST',body:{bundle:JSON.parse(text.value),replace_existing:replace.value}});rows.value=d.papers;validated.value=text.value})}
async function save(){await run(async()=>{if(validated.value!==text.value)throw Error('Preview first.');const d=await api('/admin/ai-solutions/bundle/import',{method:'POST',body:{bundle:JSON.parse(text.value),replace_existing:replace.value,save:true,publish:true}});rows.value=d.papers;validated.value='';notice.value=`${d.saved} saved · ${d.published} published · ${d.needs_review} need review. Papers with errors were skipped.`;emit('saved')})}
</script>
<template><section class="panel mt-3"><h3>Bundled solutions · up to 5 papers</h3><p>Select papers using their checkboxes. Download the ZIP and share its questions, PDFs and BUNDLE_PROMPT with your AI. It returns one bundled JSON to paste or upload below.</p><button class="btn btn-light" :disabled="busy||!paperIds.length||paperIds.length>5" @click="exportBundle">Export selected bundle ({{paperIds.length}} / 5)</button><p v-if="error" class="alert alert-danger">{{error}}</p><p v-if="notice" class="alert alert-success">{{notice}}</p><label class="d-block my-3">Upload bundled solution JSON<input type="file" accept=".json,application/json" class="form-control" :disabled="busy" @change="readFile"></label><textarea v-model="text" class="form-control" rows="8" aria-label="Bundled solution JSON" :disabled="busy" placeholder="Paste one pyq-solutions-bundle-v1 JSON here"></textarea><label class="d-block my-3"><input type="checkbox" v-model="replace" :disabled="busy"> Overwrite existing solutions included in this bundle</label><div class="d-flex flex-wrap gap-2"><button class="btn btn-light" :disabled="busy||!text" @click="preview">Preview bundle</button><button class="btn btn-primary" :disabled="busy||validated!==text||!rows.some(p=>!p.error&&p.items.length)" @click="save">Save &amp; Publish valid solutions</button></div><p class="small muted mt-3">Invalid papers are skipped. Answer-key or format warnings stay unpublished for review. Missing questions and old solutions not included in the JSON stay unchanged. Checks cannot verify mathematical reasoning.</p><article v-for="p in rows" :key="p.paper_id" class="panel mt-3"><h4>{{p.paper_name||'Paper'}} #{{p.paper_id}}</h4><p v-if="p.error" class="alert alert-danger">{{p.error}}</p><p v-else>{{p.items.length}} included · {{p.missing}} questions omitted</p><details v-for="q in p.items" :key="q.question_id"><summary>Question {{q.number}} · {{q.status}}</summary><p>Final answer: {{q.final_answer}}</p><p v-for="check in q.checks" class="alert alert-warning">{{check}}</p><MathText :text="q.text" inline-dollar/></details></article></section></template>
